-- Append-only log of Yjs updates per document. The contract is in store.ts.
-- The desktop app runs this file as its first migration (apps/desktop/src-tauri/src/lib.rs).
-- The migration runner stores a checksum of it, and a database that already ran
-- it refuses to open if the text changes. Once released, do not edit this file:
-- add a new migration instead.
CREATE TABLE IF NOT EXISTS updates (
  -- AUTOINCREMENT keeps ids strictly increasing even after rows are deleted,
  -- which the store relies on to know which updates a compaction covered.
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  doc_id TEXT NOT NULL,
  -- base64 text: the Tauri SQL plugin passes values as JSON, which has no binary type.
  data TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS updates_by_doc ON updates (doc_id, id);
